css:
.ss-check{list-style:none;margin:8px 0 20px;padding:0}
.ss-check__i{display:grid;grid-template-columns:41px minmax(0,1fr);border-bottom:1px solid var(--line)}
.ss-check__m{padding:12px 0 12px 14px;color:var(--accent);font-weight:800;font-size:15px;line-height:1.7}
.ss-check__t{padding:12px 14px;font-size:15px;line-height:1.7;color:var(--body-text)}
.ss-check__h{display:block;color:var(--ink);font-size:15px;margin-bottom:2px}
.ss-check__m::before{content:"\2713"}
.ss-check--cross .ss-check__m{color:var(--bad)}
.ss-check--cross .ss-check__m::before{content:"\2715"}
.ss-check--bullet .ss-check__m::before{content:"\2022"}
.ss-check--dot{margin:0 0 20px}
.ss-check--dot .ss-check__i{grid-template-columns:26px minmax(0,1fr);column-gap:14px;align-items:start;padding:18px 0;border-bottom:0;border-top:1px solid var(--line)}
.ss-check--dot .ss-check__i:last-child{border-bottom:1px solid var(--line)}
.ss-check--dot .ss-check__m{width:26px;height:26px;padding:0;border-radius:999px;background:var(--accent);color:var(--card);font-size:13px;line-height:1;display:flex;align-items:center;justify-content:center}
.ss-check--dot .ss-check__t{padding:0;font-size:15.5px;line-height:1.6;font-weight:600}
.ss-check--xdot .ss-check__m::before,.ss-check--xdot-ink .ss-check__m::before{content:"\2715"}
.ss-check--xdot,.ss-check--xdot-ink{margin:0 0 20px}
.ss-check--xdot .ss-check__i,.ss-check--xdot-ink .ss-check__i{grid-template-columns:26px minmax(0,1fr);column-gap:14px;align-items:start;padding:18px 0;border-bottom:0;border-top:1px solid var(--line)}
.ss-check--xdot .ss-check__i:last-child,.ss-check--xdot-ink .ss-check__i:last-child{border-bottom:1px solid var(--line)}
.ss-check--xdot .ss-check__m,.ss-check--xdot-ink .ss-check__m{width:26px;height:26px;margin-top:2px;padding:0;border-radius:999px;background:var(--accent);color:var(--card);font-size:13px;line-height:1;display:flex;align-items:center;justify-content:center}
.ss-check--xdot-ink .ss-check__m{background:var(--ink)}
.ss-check--xdot .ss-check__t,.ss-check--xdot-ink .ss-check__t{padding:0;font-size:14.5px;line-height:1.65}
.ss-check--xdot .ss-check__h,.ss-check--xdot-ink .ss-check__h{font:800 15.5px/1.3 var(--font-heading);margin:0 0 4px}
.ss-check--tick-ink{margin:0}
.ss-check--tick-ink .ss-check__i{grid-template-columns:22px minmax(0,1fr);column-gap:12px;align-items:start;padding:14px 0;border-bottom:0;border-top:1px solid var(--line)}
.ss-check--tick-ink .ss-check__m{width:22px;height:22px;margin-top:2px;padding:0;border-radius:999px;background:var(--ink);color:var(--card);font-size:11px;line-height:1;display:flex;align-items:center;justify-content:center}
.ss-check--tick-ink .ss-check__t{padding:0;font-size:13.5px;line-height:1.6}
.ss-check--tick-ink .ss-check__h{font:700 14.5px/1.7 var(--font-heading);margin:0 0 3px}
.ss-check--run .ss-check__h{display:inline;font-size:inherit;margin:0 .25em 0 0}
.ss-check--num{counter-reset:ss-check}
.ss-check--num .ss-check__m::before{counter-increment:ss-check;content:counter(ss-check,decimal-leading-zero)}
